def choose_move(observation):
    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def first_present(keys, default=None):
        for k in keys:
            if isinstance(observation, dict) and k in observation:
                return observation.get(k)
        return default

    def as_pos(x):
        if x is None:
            return None
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        if isinstance(x, dict):
            if "pos" in x:
                return as_pos(x.get("pos"))
            if "x" in x and "y" in x:
                return [x.get("x"), x.get("y")]
        return None

    def extract_all_positions(obj):
        out = []
        if obj is None:
            return out
        if isinstance(obj, dict):
            if "pos" in obj:
                p = as_pos(obj.get("pos"))
                if p is not None:
                    out.append(p)
            elif "x" in obj and "y" in obj:
                out.append([obj.get("x"), obj.get("y")])
            else:
                for v in obj.values():
                    out.extend(extract_all_positions(v))
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                if isinstance(item, (list, tuple)) and len(item) >= 2 and not isinstance(item[0], (list, tuple, dict)):
                    out.append([item[0], item[1]])
                else:
                    out.extend(extract_all_positions(item))
        return out

    def dist2(a, b):
        return (a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1])

    me = as_pos(first_present(["self", "agent", "player", "my_pos", "position", "pos"]))
    if me is None:
        me = as_pos(first_present(["agent_pos", "player_pos"]))
    if me is None:
        me = [0, 0]

    step = first_present(["step", "turn", "tick"], 0)
    try:
        step = int(step)
    except Exception:
        step = 0

    resources = extract_all_positions(first_present(["resources", "resource", "targets", "items", "food", "gold"]))
    enemies = extract_all_positions(first_present(["enemies", "enemy", "opponents", "opponent", "threats", "enemy_positions"]))
    allies = extract_all_positions(first_present(["allies", "teammates", "friends"]))
    bases = extract_all_positions(first_present(["bases", "base", "home", "homes", "caps", "capitals"]))
    territory = extract_all_positions(first_present(["territory", "frontier", "regions"]))

    # Sometimes observations contain nested state with "agents"
    agents = first_present(["agents", "units", "entities"])
    if isinstance(agents, (list, tuple)):
        for a in agents:
            if isinstance(a, dict):
                team = a.get("team", a.get("side"))
                p = as_pos(a.get("pos", a))
                if p is not None and team is not None:
                    if str(team).lower() in ("enemy", "opponent", "foe", "red", "2"):
                        enemies.append(p)
                    elif str(team).lower() in ("ally", "friend", "self", "blue", "1"):
                        allies.append(p)

    # Remove our own position if accidentally included
    resources = [p for p in resources if p != me]
    enemies = [p for p in enemies if p != me]
    bases = [p for p in bases if p != me]

    # Determine a simple threat score
    nearest_enemy = None
    nd = None
    for p in enemies:
        d = dist2(me, p)
        if nd is None or d < nd:
            nd = d
            nearest_enemy = p

    nearest_resource = None
    rd = None
    for p in resources:
        d = dist2(me, p)
        if rd is None or d < rd:
            rd = d
            nearest_resource = p

    nearest_base = None
    bd = None
    for p in bases:
        d = dist2(me, p)
        if bd is None or d < bd:
            bd = d
            nearest_base = p

    # Basic mode inference
    mode = first_present(["mode", "scenario", "game_type", "task"], "")
    mode = str(mode).lower() if mode is not None else ""

    # If there are enemies and no resources, likely pursuit/evasion or territory_control.
    # If resources exist, prioritize collection unless threatened.
    move_to = None

    if nearest_enemy is not None and nd is not None and nd <= 8:
        # evade if very close, unless obviously in territory control and we can pressure a base
        if nearest_resource is not None and rd is not None and rd < nd * 2:
            move_to = nearest_resource
        elif nearest_base is not None and bd is not None and (mode.find("territ") >= 0 or mode.find("control") >= 0):
            # if near a base in territory control, sometimes move to it
            move_to = nearest_base
        else:
            dx = me[0] - nearest_enemy[0]
            dy = me[1] - nearest_enemy[1]
            return [clamp(dx), clamp(dy)]

    if nearest_resource is not None:
        move_to = nearest_resource
    elif nearest_base is not None:
        move_to = nearest_base
    elif territory:
        move_to = territory[0]
    elif nearest_enemy is not None:
        # pursuit if no better objective
        move_to = nearest_enemy

    if move_to is None:
        # deterministic exploration
        pattern = step % 4
        if pattern == 0:
            return [1, 0]
        if pattern == 1:
            return [0, 1]
        if pattern == 2:
            return [-1, 0]
        return [0, -1]

    dx = clamp(move_to[0] - me[0])
    dy = clamp(move_to[1] - me[1])

    # If both directions nonzero, prefer axis with larger gap for cleaner movement.
    ax = abs(move_to[0] - me[0])
    ay = abs(move_to[1] - me[1])

    if ax > ay:
        dy = 0
    elif ay > ax:
        dx = 0
    else:
        # tie-break deterministically by step to add a little coverage
        if step % 2 == 0:
            dy = 0
        else:
            dx = 0

    return [dx, dy]

